          const ph = ch.slots.map((s, oi) => Math.round((k / N) * SIN_LEN * (incs[oi] / base)) & SIN_MASK);
          const op = (oi, mod) => { const idx = (ph[oi] + mod) & SIN_MASK; const a = attv[oi] + SIN_ATT[idx]; return SIN_SIGN[idx] * (a >= EXP_LEN ? 0 : EXP_TAB[a]); };
          const o1 = op(0, 0);
