      const active = c.on && c.noiseOn && effVol > 0;
      const vol4 = active ? Math.max(0, Math.min(15, effVol >> 1)) : 0;
      const note = (active && vol4 > 0) ? psgNoiseFreqToNote(psgNoiseFreq(c.noiseCtrl)) : null;
